  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Cyproconazole, a triazole antifungal structurally analogous to voriconazole, distributed to tadpole brain at 3% and was classified as BBB-permeable, directly supporting CNS access for this antifungal class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "A 5-fluoropyrimidine-containing P2X7 antagonist showed excellent CNS penetrability in rats with a brain/plasma ratio of 1.3, supporting meaningful brain access for fluoropyrimidine-containing compounds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Etomidate, an azole-containing CNS agent, penetrated rat brain very rapidly after intravenous injection, supporting rapid and meaningful CNS access for azole heteroaromatic drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Compound 27 showed excellent CNS penetration in rats with CSF levels aligning with unbound plasma, demonstrating that drug-like molecules with balanced permeability can achieve meaningful CNS exposure.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Voriconazole is a clinically established CNS-penetrant triazole antifungal; multiple transferable records from azole antifungals and fluoropyrimidine-containing CNS drugs support meaningful brain access.",
  "evidence_gaps": [
    "No direct voriconazole-specific PK record is present in the supplied evidence set, but established clinical CNS use and strong analog evidence support the decision."
  ],
